var e={"term.setting":`コードモード`,"term.settingDesc":`Claude とコードを書くためのモードです。セッションごとの別コピー（専用のブランチとフォルダ。Claude が作成・監視するプルリクエストで完了）と、会話の下のターミナル（Ctrl+J、/terminal）をセッションの git リポジトリで開けます。各回答の変更（差分、コミット、プッシュ、プルリクエスト）とプルリクエストの表示は、このモードがなくても使えます。エージェントでは使えません。オンにするにはパスワードが必要です。`,"term.enableTitle":`コードモードをオンにする`,"term.enableDesc":`コードモードでは、このサーバー上でその権限で任意のコマンドを実行できるターミナルと、セッション用のリポジトリの別コピーが追加されます。確認のためパスワードを入力してください。`,"term.password":`パスワード`,"term.badPassword":`パスワードが正しくありません`,"term.enable":`オンにする`,"term.openFailed":`ターミナルを開けませんでした`,"term.tooMany":`ターミナルが 4 つ開いています：先に 1 つ閉じてください`,"term.close":`このターミナルを閉じる`,"term.new":`新しいターミナル`,"term.quote":`選択範囲を Claude に送信`,"term.openCount":`{count} 件開いています`,"term.openCount#one":`{count} 件開いています`,"term.closeAll":`すべて閉じる`,"term.hide":`ターミナルを隠す`,"term.opening":`開いています…`,"term.ended":`[ターミナルが終了しました]`,"term.topicFolder":`トピックのフォルダ`};export{e as default};